function updateStorageWarning(){const n=$('#storageWarning');if(!n)return;n.hidden=storageMode==='ok';const recovery=$('#recoverSave');if(recovery)recovery.hidden=!['damaged','unreadable'].includes(storageMode);n.textContent=storageMode==='conflict'?'다른 탭에서 저장했어요. 필요하면 수동 슬롯에 보관한 뒤 새로고침해 최신 진행을 불러오세요.':storageMode==='damaged'||storageMode==='unreadable'?'저장 데이터를 읽을 수 없어 원본을 보존하고 있습니다. 현재 플레이는 저장되지 않으며 설정에서 새 게임을 선택하면 기존 저장을 덮어씁니다.':storageMode==='unavailable'?'브라우저 저장소를 사용할 수 없어 현재 진행이 저장되지 않습니다.':''}
function commitSnapshot(snapshot) {
 if(saveGuard)return saveGuard.write(snapshot);
 localStorage.setItem(KEY,JSON.stringify(snapshot));
}
function save() {
 if(['damaged','unreadable','conflict'].includes(storageMode)){updateStorageWarning();return false}
 const current=state;if(activeStory&&!activeStory.replay&&current.pendingStory?.id===activeStory.id){const s=activeStoryDefinition();const beatId=s.lines[storyIndex]?.[3]?.beatId||s.choice?.options[activeStory.choice]?.beatId;if(beatId)current.pendingStory.beatId=beatId;}const status=$('#saveStatus');if(status)status.textContent='저장 중…';
 const success=revision=>{if(status)status.textContent='저장됨';if(revision!==undefined)current.revision=revision;storageMode='ok';updateStorageWarning();return true};
 const failure=error=>{window.RingDiagnostics?.record(error?.name==='RingSaveConflict'?'SAVE_CONFLICT':'SAVE_WRITE');if(status)status.textContent='저장 실패';storageMode=error?.name==='RingSaveConflict'?'conflict':'unavailable';updateStorageWarning();return false};
 try{
  const result=commitSnapshot(current);
  return result?.then?result.then(success,failure):success(result);
 }catch(error){return failure(error)}
}


