function failureSummary(){const f=state.failures,stock=f.stockWait+f.cancelled;const causes=[{n:stock,text:'재료 부족',advice:'부족했던 재료를 다음 영업 전에 보충해 보세요.'},{n:f.wait,text:'대기 시간 초과',advice:'완성된 주문을 먼저 서빙하거나 작업 우선순위를 바꿔 보세요.'},{n:state.turnedAway,text:'만석',advice:'혼잡한 공연일에는 좌석 확장을 고려해 보세요.'},{n:state.priceWalkouts,text:'가격 거절',advice:'가격과 메뉴별 수용률을 함께 살펴보세요.'},{n:state.varietyWalkouts,text:'메뉴 부족',advice:'판매 메뉴의 종류를 늘리는 방안을 살펴보세요.'}].sort((a,b)=>b.n-a.n);const top=causes[0];return top.n?(f.complete?'가장 많았던 이유: ':'기록된 이유 중: ')+top.text+' '+top.n+'건. '+top.advice:'오늘 기록된 이탈 원인이 없습니다.'}
let noticeTimer=null;function clearServiceNotice(){if(noticeTimer!==null)clearTimeout(noticeTimer);noticeTimer=null;const node=$('#serviceNotice');if(node){node.hidden=true;node.textContent=''}}
function serviceNotice(message,reason=''){const node=$('#serviceNotice');if(!node)return;if(noticeTimer!==null)clearTimeout(noticeTimer);node.textContent=message;if(node.dataset)node.dataset.reason=reason;node.hidden=false;noticeTimer=setTimeout(()=>{node.hidden=true;noticeTimer=null},4500)}
function emptyOrderText(){return state.phase==='prep'?'준비 화면에서 문을 열어 주세요.':state.phase==='closed'?'오늘 영업이 끝났습니다.':'아직 기다리는 손님이 없습니다.'}
