 return `<div class="order-card-title"><span class="menu-art art-${m.id}" aria-hidden="true"></span><strong>${m.name}</strong><span>${c.regularName?'단골 '+c.regularName:'#'+c.id}</span></div><div class="order-meta"><span>${label}</span><span data-patience="${c.id}">기다림 ${Math.max(0,c.patience)}초</span><span>¥${c.price??m.price}</span></div><div class="bar"><i data-patience-bar="${c.id}" class="${c.patience<10?'low':''}" style="width:${Math.max(0,c.patience/c.maxPatience*100)}%"></i></div><div class="order-action">${c.status==='waiting'&&shortage?`<span class="order-shortage" data-shortage="${c.id}">${shortage}</span>`:''}${c.status==='waiting'?`<button data-make="${c.id}" aria-label="${m.name} 주문 ${c.id} 직접 제조" ${state.workers.taki||!hasStock(m)||tutorialBlocks(c.id,'make')?'disabled':''}>${hasStock(m)?'직접 제조':'재료 부족'}</button><button data-cancel="${c.id}" aria-label="${m.name} 주문 ${c.id} 품절 취소" ${hasStock(m)?'hidden':''} ${tutorialBlocks(c.id,'make')?'disabled':''}>품절 취소</button>`:''}${c.status==='ready'?`<button data-serve="${c.id}" aria-label="${m.name} 주문 ${c.id} 직접 서빙" ${state.workers.taki||tutorialBlocks(c.id,'serve')?'disabled':''}>직접 서빙</button>`:''}${c.status==='making'||c.status==='serving'?`<span class="muted">${label}</span>`:''}</div>`;
